//-----------------------------------------------------------------------------
inline Real calcDistSqr(const Coord3D& lhs, const Coord3D& rhs)
{
	return sqr(lhs.x - rhs.x) + sqr(lhs.y - rhs.y) + sqr(lhs.z - rhs.z);
}

